const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('console', m => {
    if (m.type() === 'error') errors.push(m.text());
  });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));

  await page.goto('http://localhost:48123/demo.html', { waitUntil: 'networkidle' });

  const boardInfo = await page.evaluate(() => {
    const out = [];
    for (const id of ['board-1', 'board-2', 'board-3', 'board-4', 'board-5']) {
      const wrap = document.getElementById(id);
      const board = wrap ? wrap.querySelector('cg-board') : null;
      out.push({
        id,
        hasBoard: !!board,
        squares: board ? board.querySelectorAll('cg-square').length : 0,
        pieces: board ? board.querySelectorAll('cg-piece').length : 0,
      });
    }
    return out;
  });
  console.log('boards: ' + JSON.stringify(boardInfo));

  const before = await page.evaluate(() => document.querySelector('#board-1 > cg-board').getBoundingClientRect().width);
  await page.evaluate(() => {
    document.querySelector('.chessground').style.cssText = 'width:300px;height:300px';
  });
  await page.waitForTimeout(600);
  const after = await page.evaluate(() => ({
    board: document.querySelector('#board-1 > cg-board').getBoundingClientRect().width,
    wrap: document.querySelector('#board-1').getBoundingClientRect().width,
  }));
  console.log('board-1 width before resize: ' + before);
  console.log('after resize: ' + JSON.stringify(after));
  await page.screenshot({ path: 'C:/Users/lokta/AppData/Local/Temp/tmp.lOpDiFujfl/demo-after-resize.png' });
  console.log('console errors: ' + JSON.stringify(errors));
  await browser.close();
})().catch(e => {
  console.error('FAILED: ' + e.message);
  process.exit(1);
});

