const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('console', m => {
    if (m.type() === 'error') errors.push(m.text());
  });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));

  // instrument ResizeObserver: track live instances and callback fires
  await page.addInitScript(() => {
    const RealRO = window.ResizeObserver;
    window.__ro = { live: 0, fires: 0 };
    window.ResizeObserver = class extends RealRO {
      constructor(cb) {
        super(cb);
        window.__ro.live++;
        const wrapped = entries => {
          window.__ro.fires++;
          cb(entries);
        };
        this.observe = el => super.observe(el);
        this.disconnect = () => {
          window.__ro.live--;
          super.disconnect();
        };
        // store wrapped cb so constructor uses it
        this.__cb = wrapped;
        super(cb === undefined ? undefined : wrapped);
      }
    };
  });

  await page.goto('http://localhost:48123/demo.html', { waitUntil: 'networkidle' });

  const boardInfo = await page.evaluate(() => {
    const out = [];
    for (const id of ['board-1', 'board-2', 'board-3', 'board-4', 'board-5']) {
      const wrap = document.getElementById(id);
      const board = wrap ? wrap.querySelector('cg-board') : null;
      out.push({
        id,
        hasBoard: !!board,
        squares: board ? board.querySelectorAll('square').length : 0,
        pieces: board ? board.querySelectorAll('piece').length : 0,
      });
    }
    return { boards: out, ro: window.__ro, containerWidth: document.querySelector('#board-1 cg-container').style.width };
  });
  console.log('boards: ' + JSON.stringify(boardInfo.boards));
  console.log('initial RO state: ' + JSON.stringify(boardInfo.ro) + ' container width: ' + boardInfo.containerWidth);

  const before = boardInfo.ro.fires;
  const containerBefore = await page.evaluate(() => document.querySelector('#board-1 cg-container').getBoundingClientRect().width);
  await page.evaluate(() => {
    document.querySelector('.chessground').style.cssText = 'width:300px;height:300px';
  });
  await page.waitForTimeout(600);
  const after = await page.evaluate(() => ({
    ro: window.__ro,
    containerWidth: document.querySelector('#board-1 cg-container').style.width,
    containerRect: document.querySelector('#board-1 cg-container').getBoundingClientRect().width,
    wrapRect: document.querySelector('#board-1').getBoundingClientRect().width,
  }));
  console.log('resize: container rect before ' + containerBefore + ' -> after ' + after.containerRect + ' (wrap ' + after.wrapRect + ')');
  console.log('RO fires before resize: ' + before + ' -> after: ' + after.ro.fires + ' (lives: ' + after.ro.live + ')');
  console.log('container style width: ' + after.containerWidth);

  await page.screenshot({ path: 'C:/Users/lokta/AppData/Local/Temp/tmp.lOpDiFujfl/demo-after-resize.png' });
  console.log('console errors: ' + JSON.stringify(errors));
  await browser.close();

  const ok =
    boardInfo.boards.every(b => b.hasBoard && b.squares === 64 && b.pieces === 32) &&
    boardInfo.ro.live === 5 &&
    after.ro.fires > before &&
    Math.abs(after.containerRect - 300) < 2;
  console.log(ok ? 'DEMO CHECK: PASS' : 'DEMO CHECK: FAIL');
  process.exit(ok ? 0 : 1);
})().catch(e => {
  console.error('FAILED: ' + e.message);
  process.exit(1);
});

