const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('console', m => {
    if (m.type() === 'error') errors.push(m.text());
  });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));

  // instrument ResizeObserver: track live instances and callback fires
  await page.addInitScript(() => {
    const RealRO = window.ResizeObserver;
    window.__ro = { live: 0, fires: 0 };
    window.ResizeObserver = class {
      constructor(cb) {
        this.__real = new RealRO(entries => {
          window.__ro.fires++;
          cb(entries);
        });
        window.__ro.live++;
      }
      observe(el) {
        this.__real.observe(el);
      }
      unobserve(el) {
        this.__real.unobserve(el);
      }
      disconnect() {
        window.__ro.live--;
        this.__real.disconnect();
      }
    };
  });

  await page.goto('http://localhost:48123/demo.html', { waitUntil: 'networkidle' });

  const boardInfo = await page.evaluate(() => {
    const out = [];
